func unifiStepNumber(step string) int {
	switch step {
	case "networks":
		return 2
	case "zones":
		return 3
	case "review":
		return 4
	default:
		return 1
	}
}

func unifiStepClass(step string, position int) string {
	current := unifiStepNumber(step)
	if current > position {
		return "complete"
	}
	if current == position {
		return "current"
	}
	return ""
}

func unifiStepMarker(step string, position int) string {
	if unifiStepNumber(step) > position {
		return "✓"
	}
	return strconv.Itoa(position)
}

func unifiNextLabel(step string) string {
	switch step {
	case "networks":
		return "Map Zones"
	case "zones":
		return "Review Changes"
	default:
		return "Connect"
	}
}

func unifiPreviousStep(step string) string {
	switch step {
	case "networks":
		return "connect"
	case "zones":
		return "networks"
	case "review":
		return "zones"
	default:
		return ""
	}
}

func unifiStepProblem(step string) string {
	switch step {
	case "networks":
		return "Choose at least one network"
	case "zones":
		return "Check the zone mapping"
	default:
		return "Could not reach the controller"
	}
}

// unifiStatusPoll tightens the refresh while a synchronization is in flight so
// the spinner and progress bar clear promptly, and backs off when idle.
func dynamicDNSNames(value string) []string {
	names := make([]string, 0)
	for _, name := range strings.Split(value, "\n") {
		if name = strings.TrimSpace(name); name != "" {
			names = append(names, name)
		}
	}
	return names
}

func dynamicDNSIPv4(view DynamicDNSAppView) string {
	return ifThen(view.Status.IPv4 != "", view.Status.IPv4, "—")
}

func dynamicDNSIPv6(view DynamicDNSAppView) string {
	for _, publisher := range view.Publishers {
		for _, zone := range publisher.Zones {
			if zone.PublishIPv6 {
				return ifThen(view.Status.IPv6 != "", view.Status.IPv6, "—")
			}
		}
	}
	return "—"
}

func dynamicDNSZoneTypeLabel(view DynamicDNSZoneView) string {
	if view.PublishIPv4 && view.PublishIPv6 {
		return "A, AAAA"
	}
	if view.PublishIPv6 {
		return "AAAA"
	}
	return "A"
}

func dynamicDNSProvidersLabel(view DynamicDNSAppView) string {
	if len(view.Publishers) == 1 {
		return dynamicDNSProviderLabel(view.Publishers[0].Provider)
	}
	return fmt.Sprintf("%d configured", len(view.Publishers))
}

func dynamicDNSPublisherOverview(view DynamicDNSPublisherView) string {
	names := 0
	for _, zone := range view.Zones {
		names += len(dynamicDNSNames(zone.Names))
	}
	return fmt.Sprintf("%d %s · %d %s", len(view.Zones), dynamicDNSPlural(len(view.Zones), "zone", "zones"), names, dynamicDNSPlural(names, "host", "hosts"))
}

func dynamicDNSPublisherHeading(view DynamicDNSPublisherView) string {
	if provider := dynamicDNSProviderLabel(view.Provider); provider != "" {
		return provider
	}
	return "Choose a provider"
}

func dynamicDNSZoneOverview(view DynamicDNSZoneView) string {
	names := len(dynamicDNSNames(view.Names))
	return fmt.Sprintf("%d %s · %s", names, dynamicDNSPlural(names, "host", "hosts"), dynamicDNSZoneTypeLabel(view))
}

func dynamicDNSZoneHeading(view DynamicDNSZoneView) string {
	if view.Zone == "" {
		return "New zone"
	}
	return view.Zone
}

func dynamicDNSPlural(count int, singular, plural string) string {
	if count == 1 {
		return singular
	}
	return plural
}

func dynamicDNSProviderLabel(provider string) string {
	switch provider {
	case "cloudflare":
		return "Cloudflare"
	case "porkbun":
		return "Porkbun"
	case "namecheap":
		return "Namecheap"
	case "godaddy":
		return "GoDaddy"
	case "digitalocean":
		return "DigitalOcean"
	case "hetzner":
		return "Hetzner"
	case "route53":
		return "Amazon Route 53"
	case "ovh":
		return "OVHcloud"
	case "rfc2136":
		return "RFC 2136"
	default:
		return provider
	}
}

func dynamicDNSStatusPoll(running bool) string {
	if running {
		return "every 1s"
	}
	return "every 30s"
}

func dynamicDNSBadgeClass(view DynamicDNSAppView) string {
	if !view.Available || !view.Configured || !view.Enabled {
		return "status-badge"
	}
	if view.Status.LastError != "" || !view.CredentialsConfigured {
		return "status-badge danger"
	}
	return "status-badge success"
}

func dynamicDNSBadgeLabel(view DynamicDNSAppView) string {
	if !view.Available {
		return "Unavailable"
	}
	if !view.Configured {
		return "Not set up"
	}
	if !view.Enabled {
		return "Paused"
	}
	if !view.CredentialsConfigured {
		return "Needs credentials"
	}
	if view.Status.LastError != "" {
		return "Needs attention"
	}
	return "Active"
}

func unifiStatusPoll(running bool) string {
	if running {
		return "every 1s"
	}
	return "every 10s"
}

func unifiNetworkFieldID(index int) string {
	return "unifi-network-" + strconv.Itoa(index)
}

func unifiRowTTL(ttl uint32) uint32 {
	if ttl == 0 {
		return 300
	}
	return ttl
}

